#!/usr/bin/env python3
"""Seeded dungeon generator.

Generates a 48x32 tile map:
  - 8-12 non-overlapping rectangular rooms
  - L-shaped corridors connecting consecutive room centers
  - walls everywhere else

Fully deterministic given a seed (uses a private random.Random instance).
"""

from __future__ import annotations

import argparse
import hashlib
import random

WIDTH = 48
HEIGHT = 32
MIN_ROOMS = 8
MAX_ROOMS = 12

WALL = "#"
FLOOR = "."


def generate_map(seed: int) -> list[str]:
    """Return the dungeon as a list of row strings (index 0 = top row)."""
    rng = random.Random(seed)
    grid = [[WALL] * WIDTH for _ in range(HEIGHT)]

    rooms = _place_rooms(rng)
    for (x0, y0, x1, y1) in rooms:
        _carve_rect(grid, x0, y0, x1, y1)

    # Connect consecutive room centers with L-shaped corridors.
    for (_, _, _, prev), (_, _, _, cur) in zip(rooms, rooms[1:]):
        cx0, cy0 = _center(*prev)
        cx1, cy1 = _center(*cur)
        _carve_l_corridor(grid, cx0, cy0, cx1, cy1, rng)

    return ["".join(row) for row in grid]


def _center(x0: int, y0: int, x1: int, y1: int) -> tuple[int, int]:
    return (x0 + x1) // 2, (y0 + y1) // 2


def _room_fits(x0: int, y0: int, x1: int, y1: int) -> bool:
    """Room must stay strictly inside the border (no wall/floor on edge)."""
    return 1 <= x0 <= x1 <= WIDTH - 2 and 1 <= y0 <= y1 <= HEIGHT - 2


def _overlaps(a: tuple[int, int, int, int], b: tuple[int, int, int, int]) -> bool:
    ax0, ay0, ax1, ay1 = a
    bx0, by0, bx1, by1 = b
    return not (ax1 + 1 < bx0 or bx1 + 1 < ax0 or ay1 + 1 < by0 or by1 + 1 < ay0)


def _place_rooms(rng: random.Random) -> list[tuple[int, int, int, int]]:
    """Place MIN_ROOMS..MAX_ROOMS non-overlapping rooms as (x0, y0, x1, y1)."""
    target = rng.randint(MIN_ROOMS, MAX_ROOMS)
    rooms: list[tuple[int, int, int, int]] = []
    attempts = 0
    while len(rooms) < target and attempts < 2000:
        attempts += 1
        w = rng.randint(4, 9)
        h = rng.randint(3, 6)
        x = rng.randint(1, WIDTH - 2 - w)
        y = rng.randint(1, HEIGHT - 2 - h)
        candidate = (x, y, x + w - 1, y + h - 1)
        if not _room_fits(*candidate):
            continue
        if any(_overlaps(candidate, r) for r in rooms):
            continue
        rooms.append(candidate)
    if len(rooms) < MIN_ROOMS:
        raise RuntimeError(f"could only place {len(rooms)} rooms")
    return rooms


def _carve_rect(grid: list[list[str]], x0: int, y0: int, x1: int, y1: int) -> None:
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            grid[y][x] = FLOOR


def _carve_l_corridor(
    grid: list[list[str]],
    x0: int, y0: int,
    x1: int, y1: int,
    rng: random.Random,
) -> None:
    """Horizontal-then-vertical (or vice versa, randomly) L corridor."""
    def carve_h(xa: int, xb: int, y: int) -> None:
        for x in range(min(xa, xb), max(xa, xb) + 1):
            grid[y][x] = FLOOR

    def carve_v(ya: int, yb: int, x: int) -> None:
        for y in range(min(ya, yb), max(ya, yb) + 1):
            grid[y][x] = FLOOR

    if rng.random() < 0.5:
        carve_h(x0, x1, y0)
        carve_v(y0, y1, x1)
    else:
        carve_v(y0, y1, x0)
        carve_h(x0, x1, y1)


def map_string(seed: int) -> str:
    """Full map as one newline-separated string."""
    return "\n".join(generate_map(seed))


def map_hash(seed: int) -> str:
    """sha256 hex digest of the tile string (rows joined without newlines)."""
    tiles = "".join(generate_map(seed))
    return hashlib.sha256(tiles.encode("ascii")).hexdigest()


def main() -> None:
    parser = argparse.ArgumentParser(description="Seeded dungeon generator")
    parser.add_argument("--seed", type=int, default=7, help="random seed")
    args = parser.parse_args()
    print(map_string(args.seed))


if __name__ == "__main__":
    main()

"""Invariant tests for the seeded dungeon generator."""

import hashlib

import pytest

from dungeon import (
    FLOOR,
    HEIGHT,
    MAX_ROOMS,
    MIN_ROOMS,
    WIDTH,
    generate_map,
    map_hash,
)

SEEDS = range(1, 31)


def _grid(rows):
    return [list(r) for r in rows]


def _floor_tiles(rows):
    return {
        (x, y)
        for y, row in enumerate(rows)
        for x, ch in enumerate(row)
        if ch == FLOOR
    }


@pytest.fixture(scope="module", params=list(SEEDS))
def dungeon(request):
    rows = generate_map(request.param)
    yield request.param, rows


# --- shape ---------------------------------------------------------------

def test_dimensions(dungeon):
    _, rows = dungeon
    assert len(rows) == HEIGHT
    assert all(len(r) == WIDTH for r in rows)


def test_only_floor_and_wall(dungeon):
    _, rows = dungeon
    assert set("".join(rows)) == {FLOOR, "#"}


# --- invariants ----------------------------------------------------------

def test_room_count_within_bounds(dungeon):
    seed, rows = dungeon
    # A room is a maximal axis-aligned rectangle of floor fully surrounded
    # above/below by walls. Count distinct room "interiors": floor tiles that
    # have wall directly above them mark room tops... Simpler robust check:
    # count connected components of floor wider/taller than corridor width.
    # Instead, verify via generator contract: re-run placement logic bounds by
    # counting horizontal floor runs of length >= 4 bounded by walls.
    import dungeon as d

    rng_rooms = d._place_rooms(__import__("random").Random(seed))
    assert MIN_ROOMS <= len(rng_rooms) <= MAX_ROOMS
    # The generated map must contain exactly these rooms carved.
    for (x0, y0, x1, y1) in rng_rooms:
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                assert rows[y][x] == FLOOR, f"room tile ({x},{y}) not floor"


def test_no_room_touches_border(dungeon):
    import random

    import dungeon as d

    seed, rows = dungeon
    rooms = d._place_rooms(random.Random(seed))
    for (x0, y0, x1, y1) in rooms:
        assert 1 <= x0 and x1 <= WIDTH - 2, f"room {rooms} touches left/right border"
        assert 1 <= y0 and y1 <= HEIGHT - 2, f"room {rooms} touches top/bottom border"


def test_single_connected_component(dungeon):
    _, rows = dungeon
    floors = _floor_tiles(rows)
    start = next(iter(floors))
    seen = {start}
    stack = [start]
    while stack:
        x, y = stack.pop()
        for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
            if (nx, ny) in floors and (nx, ny) not in seen:
                seen.add((nx, ny))
                stack.append((nx, ny))
    assert seen == floors, (
        f"unreachable floor: {floors - seen!r} of {len(floors)} tiles"
    )


# --- determinism / diversity ---------------------------------------------

def test_same_seed_identical():
    for seed in SEEDS:
        a = "\n".join(generate_map(seed))
        b = "\n".join(generate_map(seed))
        ha = hashlib.sha256(a.encode()).hexdigest()
        hb = hashlib.sha256(b.encode()).hexdigest()
        assert ha == hb


def test_different_seeds_distinct_hashes():
    hashes = {map_hash(seed) for seed in SEEDS}
    assert len(hashes) >= 25, f"only {len(hashes)} distinct hashes over seeds 1..30"

